import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
const root = '/Users/senghyunjo/github/stax-xml';
const html = `<!doctype html><meta charset="utf-8"><title>Wasm package smoke</title><pre id="output">Loading</pre>
<script type="importmap">{"imports":{"stax-xml":"/packages/stax-xml/dist/index.js","stax-xml/converter":"/packages/stax-xml/dist/converter.js","stax-xml/experimental/backend":"/packages/stax-xml/dist/experimental/backend.js","@stax-xml/wasm":"/packages/wasm/dist/index.js","@stax-xml/wasm/converter":"/packages/wasm/dist/converter.js"}}</script>
<script type="module">
import * as wasm from '@stax-xml/wasm';
import { EventReaderSync as JsEventReaderSync } from 'stax-xml';
import { x } from 'stax-xml/converter';
import { withWasmBackend } from '@stax-xml/wasm/converter';
const check = (condition, message) => { if (!condition) throw new Error(message); };
try {
  const native = globalThis.WebAssembly;
  globalThis.WebAssembly = undefined;
  try {
    check([...new JsEventReaderSync(new TextEncoder().encode('<r/>'))].length === 4, 'JS must work without Wasm');
    check([...new wasm.EventReaderSync('<r/>')].length === 4, 'string fallback must work without Wasm');
  } finally { globalThis.WebAssembly = native; }
  const rows = [];
  for (const variant of ['scalar', 'simd']) {
    await wasm.initWasm({ variant });
    const bytes = new TextEncoder().encode('<book><title>😀&amp;東京</title><count>7</count></book>');
    const schema = x.object({ title: x.string('/book/title'), count: x.number('/book/count') });
    const result = schema.parseSync(bytes, withWasmBackend({}));
    check(result.title === '😀&東京' && result.count === 7, variant + ' converter');
    async function* chunks() { for (const byte of bytes) yield Uint8Array.of(byte); }
    const events = [];
    for await (const event of new wasm.EventReader(chunks())) events.push(event);
    check(events.filter(e => e.type === wasm.XmlEventType.CHARACTERS).map(e => e.value).join('') === '😀&東京7', variant + ' split UTF-8');
    rows.push({ variant, result, events: events.length });
  }
  window.smoke = { status: 'passed', browser: navigator.userAgent, noWasmJsFallback: true, rows };
} catch (error) { window.smoke = { status: 'failed', error: String(error), stack: error.stack }; }
document.querySelector('#output').textContent = JSON.stringify(window.smoke, null, 2);
document.querySelector('#output').dataset.status = window.smoke.status;
</script>`;
createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (path === '/') { res.setHeader('content-type', 'text/html'); res.end(html); return; }
    if (!/^\/packages\/(stax-xml|wasm)\/dist\//.test(path) || path.includes('..')) { res.writeHead(404); res.end(); return; }
    res.setHeader('content-type', path.endsWith('.wasm') ? 'application/wasm' : 'text/javascript');
    res.end(await readFile(root + path));
  } catch (error) { res.writeHead(404); res.end(String(error)); }
}).listen(4179, '127.0.0.1', () => console.log('Wasm smoke ready on 4179'));

