import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { initWasm, EventReaderSync, XmlEventType } from '@stax-xml/wasm';
import { withWasmBackend } from '@stax-xml/wasm/converter';
import { x } from 'stax-xml/converter';
const input = new TextEncoder().encode('<r>😀&amp;東京</r>');
const assets = [];
for (const variant of ['scalar', 'simd']) {
  const specifier = `@stax-xml/wasm/tokenizer.${variant}.wasm`;
  const bytes = await readFile(new URL(import.meta.resolve(specifier)));
  assert(WebAssembly.validate(bytes));
  await initWasm({ variant });
  assert.equal(x.string('/r').parseSync(input, withWasmBackend({})), '😀&東京');
  const events = [...new EventReaderSync(input)];
  assert.equal(events.find(event => event.type === XmlEventType.CHARACTERS).value, '😀&東京');
  assets.push({ specifier, bytes: bytes.length });
}
const result = { status: 'passed', variants: ['scalar', 'simd'], assets };
await writeFile('/tmp/stax/packed-consumer-result.json', JSON.stringify(result, null, 2));
console.log(JSON.stringify(result));
